package images

import (
	"os"
	"path/filepath"
	"strings"
)

// IsVetoName reports whether the file is temporary metadata generated by macOS or Windows.
func IsVetoName(name string) bool {
	base := filepath.Base(name)
	lower := strings.ToLower(base)
	if lower == ".ds_store" || lower == "thumbs.db" || lower == "desktop.ini" {
		return true
	}
	if strings.HasPrefix(base, "._") {
		return true
	}
	return false
}

// ensureDirMode creates directories and applies the requested mode and setgid bit
// to all directory levels between root and dir (inclusive of dir, exclusive of root).
func ensureDirMode(dir, root string, mode os.FileMode) error {
	cleanRoot := filepath.Clean(root)
	cleanDir := filepath.Clean(dir)

	if r, err := filepath.EvalSymlinks(cleanRoot); err == nil {
		cleanRoot = r
	}
	if r, err := filepath.EvalSymlinks(cleanDir); err == nil {
		cleanDir = r
	}

	if err := os.MkdirAll(cleanDir, mode); err != nil {
		return err
	}

	curr := cleanDir
	for {
		if curr == cleanRoot || len(curr) <= len(cleanRoot) {
			break
		}
		rel, err := filepath.Rel(cleanRoot, curr)
		if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			break
		}
		_ = os.Chmod(curr, mode)
		curr = filepath.Dir(curr)
	}
	return nil
}

// cleanEmptyParentDirs removes empty parent directories up to rootDir.
// If a directory contains only veto metadata files (e.g. .DS_Store),
// those files are removed before removing the directory.
func cleanEmptyParentDirs(filePath, rootDir string) error {
	cleanRoot := filepath.Clean(rootDir)
	cleanFile := filepath.Clean(filePath)

	if r, err := filepath.EvalSymlinks(cleanRoot); err == nil {
		cleanRoot = r
	}
	// filePath itself is likely already deleted, so evaluate symlinks on its parent directory
	parentDir := filepath.Dir(cleanFile)
	if r, err := filepath.EvalSymlinks(parentDir); err == nil {
		cleanFile = filepath.Join(r, filepath.Base(cleanFile))
	} else if r, err := filepath.EvalSymlinks(cleanFile); err == nil {
		cleanFile = r
	}

	rel, err := filepath.Rel(cleanRoot, cleanFile)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return nil
	}

	curr := filepath.Dir(cleanFile)
	for {
		if curr == cleanRoot || len(curr) <= len(cleanRoot) {
			break
		}

		relDir, err := filepath.Rel(cleanRoot, curr)
		if err != nil || relDir == "." || relDir == ".." || strings.HasPrefix(relDir, ".."+string(filepath.Separator)) {
			break
		}

		entries, err := os.ReadDir(curr)
		if err != nil {
			if os.IsNotExist(err) {
				curr = filepath.Dir(curr)
				continue
			}
			return err
		}

		var vetoFiles []string
		hasOther := false
		for _, e := range entries {
			if e.IsDir() {
				hasOther = true
				break
			}
			if IsVetoName(e.Name()) {
				vetoFiles = append(vetoFiles, filepath.Join(curr, e.Name()))
			} else {
				hasOther = true
				break
			}
		}

		if hasOther {
			break
		}

		for _, vf := range vetoFiles {
			_ = os.Remove(vf)
		}

		if err := os.Remove(curr); err != nil {
			break
		}

		curr = filepath.Dir(curr)
	}

	return nil
}
